const chainResult = $input.first().json;
const context = $('Restore Workflow Context').first().json;

let analysis = chainResult.output;
if (typeof analysis === 'string') {
  analysis = JSON.parse(analysis);
}

if (analysis === null || typeof analysis !== 'object' || Array.isArray(analysis)) {
  throw new Error('结构化销售分析结果不是 JSON 对象');
}

const normalizedAnalysis = {
  summary: analysis.summary,
  needs: [...analysis.needs],
  missing_information: [...analysis.missing_information],
  next_actions: [...analysis.next_actions],
  risk_flags: [...new Set(analysis.risk_flags)],
};

if (context.purchase_window_days === null) {
  const hasMissingQuestion = normalizedAnalysis.missing_information
    .some((value) => /采购|评估时间|时间窗口/.test(value));
  if (!hasMissingQuestion && normalizedAnalysis.missing_information.length < 5) {
    normalizedAnalysis.missing_information.push('采购评估时间');
  }

  const hasFollowupAction = normalizedAnalysis.next_actions
    .some((value) => /采购|评估时间|时间窗口/.test(value));
  if (!hasFollowupAction && normalizedAnalysis.next_actions.length < 5) {
    normalizedAnalysis.next_actions.push('向客户确认采购评估时间');
  }
}

const priority = context.purchase_window_days !== null
  && context.purchase_window_days <= 30
  ? 'high'
  : 'normal';

const reviewReasons = [...normalizedAnalysis.risk_flags];
const reviewStatus = reviewReasons.length > 0 ? 'pending' : 'not_required';

return [{
  json: {
    customer: {
      customer_id: context.customer_id,
      company_name: context.company_name,
      industry: context.industry,
      sales_owner: context.sales_owner,
    },
    run_id: context.workflow_run_id,
    event_id: context.event_id,
    requirement_snapshot: context.requirement,
    analysis: normalizedAnalysis,
    priority,
    review_status: reviewStatus,
    review_reasons: reviewReasons,
    notification_mode: 'preview',
    notification_channel: 'feishu',
  },
}];
